<script lang="ts">
import {Component} from 'vue-property-decorator'
import {PortalVueBase} from '@/view/PortalVueBase'
import {canonicalOrigin, pageMetaInfo} from '@/model/Seo'
import {Locale} from '@/model/content/Locale'
import type {CVResumeLink} from '@/model/Data/CVData'

@Component
export default class PrintableCV extends PortalVueBase {
  get cvPath() {
    return Locale.activePathFor(this.constants.cvPath)
  }

  mounted() {
    document.body.classList.add('cv-paper-print')
    if (new URLSearchParams(window.location.search).get('pdf') === '1') {
      document.body.classList.add('cv-pdf-render')
    }
  }

  beforeDestroy() {
    document.body.classList.remove('cv-paper-print', 'cv-pdf-render')
  }

  productionUrl(link: CVResumeLink) {
    return link.external ? link.url : `${canonicalOrigin}${Locale.activePathFor(link.url)}`
  }

  asciiDate(value: string) {
    return value.replace(/[\u2010-\u2015]/g, '-')
  }

  metaInfo(): any {
    const info = pageMetaInfo(
      `${this.titles.cvPage} — ${this.model.cv.openPrintableTitle}`,
      this.titles.cvDescription,
      this.constants.cvPrintPath,
      this.model.cv.photo.src
    )
    return {
      ...info,
      meta: [...info.meta, {vmid: 'robots', name: 'robots', content: 'noindex'}]
    }
  }

  print() {
    window.print()
  }
}
</script>
